import sys

class Solver:
    def execute(self, scanner, writer):
        n = int(scanner[0])
        s = scanner[1]
        totalWins = 0
        maxSegment = 0
        start = 0
        end = 0
        while "__" in s:
            s = s.replace("__", "_")
        n = len(s)

        if s[start] == '(':
            while end < n and s[end] != ')':
                end += 1
            if end < n and s[end] == ')':
                inside = s[start + 1:end]
                if "_" not in inside and len(inside) > 0:
                    totalWins += 1
                else:
                    tokens = inside.split('_')
                    totalWins += len(tokens)
                start = end + 1

        idx = 0
        while idx < n:
            if s[idx] == '(':
                closeIdx = idx
                while closeIdx < n and s[closeIdx] != ')':
                    closeIdx += 1
                if closeIdx < n and s[closeIdx] == ')':
                    inside = s[idx + 1:closeIdx]
                    if "_" not in inside and len(inside) > 0:
                        totalWins += 1
                    else:
                        tokens = inside.split('_')
                        totalWins += len(tokens)
                    idx = closeIdx
            idx += 1

        while '(' in s or ')' in s:
            import re
            s = re.sub(r'\([^()]*\)', '_', s)

        segments = s.split('_')
        for segment in segments:
            if len(segment) > maxSegment:
                maxSegment = len(segment)

        writer.write(str(maxSegment) + " " + str(totalWins) + "\n")

def main():
    input_data = sys.stdin.read().strip().split()
    output = []
    solver = Solver()
    solver.execute(input_data, output)
    print(output[0], end='')

if __name__ == "__main__":
    main()

